import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l2_p13_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor convtranspose3d_mean_add_softmax_tanh_scale_cuda(
    torch::Tensor x,
    torch::Tensor bias,
    double scaling_factor);

torch::Tensor convtranspose3d_mean_add_softmax_tanh_scale(
    torch::Tensor x,
    torch::Tensor bias,
    double scaling_factor) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(bias.dtype() == torch::kFloat32, "bias must be float32");
    return convtranspose3d_mean_add_softmax_tanh_scale_cuda(x, bias, scaling_factor);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("convtranspose3d_mean_add_softmax_tanh_scale_cuda",
          &convtranspose3d_mean_add_softmax_tanh_scale,
          "Fused mean+bias+softmax+tanh+scale");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cfloat>

__global__ void fused_post_conv_kernel(
    const float* __restrict__ x,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int N, int C, int D, int H, int W,
    float scaling_factor) {

    int spatial_idx = blockIdx.x;
    int total_spatial = N * H * W;

    if (spatial_idx >= total_spatial) return;

    int n = spatial_idx / (H * W);
    int hw = spatial_idx % (H * W);
    int h = hw / W;
    int w = hw % W;

    extern __shared__ float shared_mem[];
    float* channel_vals = shared_mem;

    int tid = threadIdx.x;
    int block_size = blockDim.x;

    for (int c = tid; c < C; c += block_size) {
        float sum = 0.0f;
        for (int d = 0; d < D; d++) {
            int idx = ((n * C + c) * D + d) * H * W + h * W + w;
            sum += x[idx];
        }
        float mean_val = sum / D;
        float bias_val = bias[c];
        channel_vals[c] = mean_val + bias_val;
    }
    __syncthreads();

    float max_val = -FLT_MAX;
    for (int c = tid; c < C; c += block_size) {
        float val = channel_vals[c];
        max_val = fmaxf(max_val, val);
    }

    __shared__ float shared_max;
    if (tid == 0) {
        shared_max = -FLT_MAX;
    }
    __syncthreads();

    atomicMax((int*)&shared_max, __float_as_int(max_val));
    __syncthreads();

    max_val = shared_max;

    float sum_exp = 0.0f;
    for (int c = tid; c < C; c += block_size) {
        float val = expf(channel_vals[c] - max_val);
        channel_vals[c] = val;
        sum_exp += val;
    }

    __shared__ float shared_sum;
    if (tid == 0) {
        shared_sum = 0.0f;
    }
    __syncthreads();

    atomicAdd(&shared_sum, sum_exp);
    __syncthreads();

    sum_exp = shared_sum;

    for (int c = tid; c < C; c += block_size) {
        float softmax_val = channel_vals[c] / sum_exp;
        float tanh_val = tanhf(softmax_val);
        float final_val = tanh_val * scaling_factor;

        int out_idx = ((n * C + c) * 1 + 0) * H * W + h * W + w;
        out[out_idx] = final_val;
    }
}

torch::Tensor convtranspose3d_mean_add_softmax_tanh_scale_cuda(
    torch::Tensor x,
    torch::Tensor bias,
    double scaling_factor) {

    int N = x.size(0);
    int C = x.size(1);
    int D = x.size(2);
    int H = x.size(3);
    int W = x.size(4);

    auto out = torch::empty({N, C, 1, H, W}, x.options());

    int total_spatial = N * H * W;
    int threads = 128;
    int blocks = total_spatial;

    size_t shared_mem_size = C * sizeof(float);

    fused_post_conv_kernel<<<blocks, threads, shared_mem_size>>>(
        x.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, D, H, W,
        static_cast<float>(scaling_factor)
    );

    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Model that performs a series of operations:
        1. Transposed 3D convolution
        2. Mean pooling (across depth)
        3. Addition
        4. Softmax (across channels)
        5. Tanh activation
        6. Scaling
        """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, scaling_factor):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding)
        self.bias = nn.Parameter(torch.randn(1, out_channels, 1, 1, 1))
        self.scaling_factor = scaling_factor
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        x = self.conv_transpose(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        x = _stark_get_extension().convtranspose3d_mean_add_softmax_tanh_scale_cuda(x, self.bias, float(self.scaling_factor))
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        # Bias add now fused into CUDA kernel
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        # Softmax now fused into CUDA kernel
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_5>>>
        # Tanh now fused into CUDA kernel
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_6>>>
        # Scaling now fused into CUDA kernel
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_7>>>
        return x
        # <<<END_IMPROVE>>>

