// One warp (32 threads) handles two output channels each, covering all 64 channels.
// Each block handles one spatial position (n, h, w).
// Threads 0..31 own channels 0..31 and 32..63 simultaneously.
__launch_bounds__(64, 4)
__global__ void fused_post_conv_tail_c64_d32(
    const float* __restrict__ x,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int N, int D, int H, int W,
    float scaling_factor) {

    // blockDim.x == 64; each thread owns one channel
    const int C = 64;
    int tid = threadIdx.x;  // channel index
    int spatial_idx = blockIdx.x;
    int HW = H * W;

    if (spatial_idx >= N * HW) return;

    int n = spatial_idx / HW;
    int hw = spatial_idx % HW;
    int h = hw / W;
    int w = hw % W;

    // Step 1: mean over depth for this channel
    float sum = 0.0f;
    const float* base = x + ((n * C + tid) * D) * HW + h * W + w;
    #pragma unroll 4
    for (int d = 0; d < D; d++) {
        sum += base[d * HW];
    }
    float val = sum * (1.0f / D) + __ldg(bias + tid);

    // Step 2: softmax over 64 channels using two-warp shuffle reduction
    // We have 64 threads; split into two warps of 32
    // Use shared memory to communicate between the two warps
    __shared__ float smem[4];  // [warp0_max, warp1_max, warp0_sum, warp1_sum]

    // --- max reduction ---
    float mx = val;
    // intra-warp reduce
    mx = fmaxf(mx, __shfl_down_sync(0xffffffff, mx, 16));
    mx = fmaxf(mx, __shfl_down_sync(0xffffffff, mx, 8));
    mx = fmaxf(mx, __shfl_down_sync(0xffffffff, mx, 4));
    mx = fmaxf(mx, __shfl_down_sync(0xffffffff, mx, 2));
    mx = fmaxf(mx, __shfl_down_sync(0xffffffff, mx, 1));

    int warp_id = tid >> 5;  // 0 or 1
    int lane    = tid & 31;
    if (lane == 0) smem[warp_id] = mx;
    __syncthreads();
    float global_max = fmaxf(smem[0], smem[1]);

    // --- exp and sum reduction ---
    float e = __expf(val - global_max);
    float es = e;
    es += __shfl_down_sync(0xffffffff, es, 16);
    es += __shfl_down_sync(0xffffffff, es, 8);
    es += __shfl_down_sync(0xffffffff, es, 4);
    es += __shfl_down_sync(0xffffffff, es, 2);
    es += __shfl_down_sync(0xffffffff, es, 1);

    if (lane == 0) smem[2 + warp_id] = es;
    __syncthreads();
    float global_sum = smem[2] + smem[3];

